import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ProdavnicaService } from '../prodavnica.service';
import jwt_decode from 'jwt-decode'; // Uvezi jwt-decode
import { Prodavnica } from '../models/prodavnica';

@Component({
  selector: 'app-infoprodavci',
  templateUrl: './infoprodavci.component.html',
  styleUrls: ['./infoprodavci.component.css']
})
export class InfoprodavciComponent {
  profilnaSlika: string | null = null;
  storeForm: FormGroup;
  isEditing: { [key: string]: boolean } = {
    ime: false,
    adresa: false,
    opis: false,
    radnoVreme: false,
    kontaktInfo: false
  };

  constructor(private fb: FormBuilder, private prodavnicaService: ProdavnicaService) {
    this.storeForm = this.fb.group({
      ime: [{ value: '', disabled: true }, Validators.required],
      adresa: [{ value: '', disabled: true }, Validators.required],
      opis: [{ value: '', disabled: true }],
      radnoVreme: [{ value: '', disabled: true }, Validators.required],
      kontaktInfo: [{ value: '', disabled: true }, Validators.required]
    });
  }

  email: string = '';

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    console.log(token);
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.email = decodedToken.email;
      this.loadStoreData();
    }
  }

  loadStoreData() {
    this.prodavnicaService.dohvatiProdavnicu(this.email).subscribe((prodavnica: Prodavnica) => {
      this.storeForm.patchValue({
        ime: prodavnica.ime,
        adresa: prodavnica.adresa,
        opis: prodavnica.opis,
        radnoVreme: prodavnica.radnoVreme,
        kontaktInfo: prodavnica.kontaktInfo
      });

      // Ažuriraj profilnu sliku nakon učitavanja podataka prodavnice
      this.profilnaSlika = prodavnica.slika ? prodavnica.slika : null;
    });
  }

  enableEditing(field: string) {
    this.isEditing[field] = true;
    this.storeForm.get(field)?.enable();
  }

  onSubmit() {
    if (this.storeForm.valid) {
      const updatedStoreData = this.storeForm.value;
      this.prodavnicaService.azuriraj(this.email, updatedStoreData).subscribe(
        (response) => {
          this.isEditing = {
            ime: false,
            adresa: false,
            opis: false,
            radnoVreme: false,
            kontaktInfo: false
          };
          this.storeForm.disable();
        },
        (error) => {
          alert('Greška pri ažuriranju podataka.');
        }
      );
    }
  }

  onImageSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const selectedFile = input.files[0];
      this.prodavnicaService.uploadProfileImage(this.email, selectedFile)
        .subscribe(
          (response) => {
            console.log('Profilna slika uspešno sačuvana:', response.slika);
            this.profilnaSlika = response.slika; // Ažuriraj prikaz na stranici
          },
          (error) => {
            console.error('Greška pri dodavanju profilne slike:', error);
          }
        );
    }
  }

  getProdavnicaImage(): string {
    if (this.profilnaSlika) {
      return `http://localhost:4000/${this.profilnaSlika}`;
    } else {
      return 'assets/default-profile.png'; // Putanja do default slike ako profilna slika nije postavljena
    }
  }
}
<div class="form-container">
  <h1>Podaci prodavnice</h1>

  <div class="form-content">
    <!-- Leva strana sa podacima -->
    <div class="form-fields">
      <form [formGroup]="storeForm" (ngSubmit)="onSubmit()">
        <div class="form-group">
          <label for="ime">Ime prodavnice:</label>
          <div class="input-container">
            <input type="text" id="ime" formControlName="ime" [readonly]="!isEditing['ime']" placeholder="Unesite ime prodavnice" />
            <span class="edit-icon" (click)="enableEditing('ime')">✎</span>
          </div>
        </div>

        <div class="form-group">
          <label for="adresa">Adresa:</label>
          <div class="input-container">
            <input type="text" id="adresa" formControlName="adresa" [readonly]="!isEditing['adresa']" placeholder="Unesite adresu prodavnice" />
            <span class="edit-icon" (click)="enableEditing('adresa')">✎</span>
          </div>
        </div>

        <div class="form-group">
          <label for="opis">Opis prodavnice:</label>
          <div class="input-container">
            <textarea id="opis" formControlName="opis" [readonly]="!isEditing['opis']" placeholder="Unesite opis prodavnice"></textarea>
            <span class="edit-icon" (click)="enableEditing('opis')">✎</span>
          </div>
        </div>

        <div class="form-group">
          <label for="radnoVreme">Radno vreme:</label>
          <div class="input-container">
            <input type="text" id="radnoVreme" formControlName="radnoVreme" [readonly]="!isEditing['radnoVreme']" placeholder="Unesite radno vreme" />
            <span class="edit-icon" (click)="enableEditing('radnoVreme')">✎</span>
          </div>
        </div>

        <div class="form-group">
          <label for="kontaktInfo">Kontakt informacije:</label>
          <div class="input-container">
            <input type="text" id="kontaktInfo" formControlName="kontaktInfo" [readonly]="!isEditing['kontaktInfo']" placeholder="Unesite kontakt informacije" />
            <span class="edit-icon" (click)="enableEditing('kontaktInfo')">✎</span>
          </div>
        </div>

        <button type="submit" [disabled]="!storeForm.valid">Sačuvaj podatke</button>
      </form>
    </div>

    <!-- Desna strana sa slikom -->
    <div class="profile-picture-container">
      <img *ngIf="profilnaSlika" [src]="getProdavnicaImage()" alt="Profilna slika" class="profile-img" />      
      <!-- Custom dugme za upload slike -->
      <label for="profileImageInput" class="custom-file-upload">
        Izaberi sliku
      </label>
      <input type="file" id="profileImageInput" (change)="onImageSelected($event)" accept="image/*" />
    </div>

  </div>
</div>
